export interface AcceptProjectTransferRequestParams {
  projectId: string;
  requestId: string;
  orgId?: string;
}

/**
 * Accepts a transfer request for the specified project, transferring it to the specified organization or user. If org_id is not passed, the project will be transferred to the current user or organization account.
 *
 * @param projectId - The Neon project ID
 * @param requestId - The Neon project transfer request ID
 * @param orgId - The Neon organization ID to transfer the project to. If not
 *   provided, the project will be transferred to the current user or organization
 *   account.
 */
export async function acceptProjectTransferRequest(
  config: ClientConfig,
  { projectId, requestId, orgId }: AcceptProjectTransferRequestParams,
  requestOptions?: RequestOptions,
): Promise<void> {
  validatePattern("project_id", projectId, "^[a-z0-9-]{1,60}$");

  validatePattern("request_id", requestId, "^[a-z0-9-]{1,60}$");

  if (orgId != null) {
    validatePattern("org_id", orgId, "^[a-z0-9-]{1,60}$");
  }

  const _resp = await sdkRequest<void>({
    method: "PUT",
    path: `/projects/${encodePathSegment(projectId)}/transfer_requests/${encodePathSegment(requestId)}`,
    operationId: "acceptProjectTransferRequest",
    errors: { "406": "AcceptProjectTransferRequestSatisfiesPlanError", default: "GeneralError" },
    responseDecoder: "empty",
    ...requestOptions,
    body: {
      org_id: orgId,
    },
    config,
  });
  void _resp.data;
  return;
}
